sysevent_script_action.script:
// Call a function to create a Scheduled Import for the oldest
// oldest attachment on Vendor Data Queue; this should always
// be the next file imported. It may not be the file whose 
// arrival triggered the event that ran this script action.
// Note that we ignore 'current' and any params.

// First get the data surce.
var scope = gs.getCurrentApplicationId();
var ds_sys_id = new x_42999_import_v_0.VendorDataUtils().getDataSourceSysId(scope, "Vendor Data Queue");

// Get the oldest attachment.
var gr = new GlideRecord("sys_attachment");
gr.addQuery("table_name", "sys_data_source");
gr.addQuery("table_sys_id", ds_sys_id);
gr.orderBy("sys_created_on");
gr.setLimit(1);
gr.query();
if(!gr.next()) throw "No data source attachment found";
queueNextImport(gr);

function queueNextImport(current) {
    // A new data file has arrived and is parked on "Vendor Data Queue".

    // Queue the file up for import via data source "Vendor Data", unless...

    // ...Exit if there is a Scheduled Data Import for this data source
    // with a future run date.
    var util = new x_42999_import_v_0.VendorDataUtils();
    var gdtNow = new GlideDateTime();
    var scope = gs.getCurrentApplicationId();
    var activeOnly = true;
    var answer = util.hasScheduledImportAfter(scope, "Vendor Data", activeOnly, gdtNow);
    if (answer == true) {
        gs.info("There is an existing scheduled import for this data. Exiting.");
        return;
    }

    // Copy all attachments from "Vendor Data" to "Vendor Data Archive",
    // and remove originals
    util.shiftAttachments("Vendor Data", "Vendor Data Archive", true);

    // Create a Scheduled Data Import for Vendor Data, set it to run soon.

    // The import's name will reflect when the file was received.
    // The run time may lag this, esp if muliple files are received
    // about the same time.
    var gr = new GlideRecord("sys_attachment");
    gr.get(attachment_sys_id);
    var name = "Vendor Data " + gr.getValue("sys_created_on");

    // run time
    var gdt = new GlideDateTime();
    gdt.addSeconds(5);
    var runStart = gdt.getDisplayValue();
    var runType = "once";
    util.createScheduledImport(
        scope,
        name,
        "Vendor Data",
        runStart,
        runType);

}
